  private formula = new Map<number, Map<number, number>>();
  constructor(height: number, width: string) {}

  private id(row: number, col: string): number {
    return (row - 1) * 26 + (col.charCodeAt(0) - 65);
  }

  private expand(numbers: string[]): Map<number, number> {
    const refs = new Map<number, number>();
    for (const s of numbers) {
      const [a, b = a] = s.split(":");
      const c1 = a.charCodeAt(0) - 65, r1 = parseInt(a.slice(1), 10);
      const c2 = b.charCodeAt(0) - 65, r2 = parseInt(b.slice(1), 10);
      for (let r = r1; r <= r2; r++)
        for (let c = c1; c <= c2; c++) {
          const key = (r - 1) * 26 + c;
          refs.set(key, (refs.get(key) ?? 0) + 1);
        }
    }
    return refs;
  }

  private evalCell(cell: number, memo: Map<number, number>): number {
    const f = this.formula.get(cell);
    if (!f) return this.val.get(cell) ?? 0;
    const hit = memo.get(cell);
    if (hit !== undefined) return hit;
    let total = 0;
    for (const [ref, count] of f) total += count * this.evalCell(ref, memo);
    memo.set(cell, total);
    return total;
  }

