    const cell = this.id(row, column);
    this.formula.delete(cell);
    this.val.set(cell, val);
  }

  get(row: number, column: string): number {
    return this.evalCell(this.id(row, column), new Map());
  }

  sum(row: number, column: string, numbers: string[]): number {
    this.formula.set(this.id(row, column), this.expand(numbers));
    return this.get(row, column);
  }
}

