class Excel {
  private val = new Array(26 * 26).fill(0);
  private formula: (Map<number, number> | null)[] = new Array(26 * 26).fill(null);
  private users: Set<number>[] = Array.from({ length: 26 * 26 }, () => new Set<number>());
  constructor(height: number, width: string) {}

  private id(row: number, col: string): number {
    return (row - 1) * 26 + (col.charCodeAt(0) - 65);
  }

  private expand(numbers: string[]): Map<number, number> {
    const refs = new Map<number, number>();
    for (const s of numbers) {
      const [a, b = a] = s.split(":");
      const c1 = a.charCodeAt(0) - 65, r1 = parseInt(a.slice(1), 10);
      const c2 = b.charCodeAt(0) - 65, r2 = parseInt(b.slice(1), 10);
      for (let r = r1; r <= r2; r++)
        for (let c = c1; c <= c2; c++) {
          const key = (r - 1) * 26 + c;
          refs.set(key, (refs.get(key) ?? 0) + 1);
        }
    }
    return refs;
  }

  private compute(cell: number): void {
    let total = 0;
    for (const [ref, count] of this.formula[cell]!) total += count * this.val[ref];
    this.val[cell] = total;
  }

  private dropFormula(cell: number): void {
    const f = this.formula[cell];
    if (f) for (const ref of f.keys()) this.users[ref].delete(cell);
    this.formula[cell] = null;
  }

  // recompute every formula that depends on cell, inputs before outputs
  private propagate(cell: number): void {
    const order: number[] = [], seen = new Set<number>();
    const dfs = (c: number) => {
      seen.add(c);
      for (const u of this.users[c]) if (!seen.has(u)) dfs(u);
      order.push(c); // post-order: all dependents are pushed before c
    };
    dfs(cell);
    for (let i = order.length - 2; i >= 0; i--) this.compute(order[i]); // skip cell itself (last)
  }

  set(row: number, column: string, val: number): void {
    const cell = this.id(row, column);
    this.dropFormula(cell);
    this.val[cell] = val;
    this.propagate(cell);
  }

  get(row: number, column: string): number {
    return this.val[this.id(row, column)];
  }

  sum(row: number, column: string, numbers: string[]): number {
    const cell = this.id(row, column);
    this.dropFormula(cell);
    const f = this.expand(numbers);
    this.formula[cell] = f;
    for (const ref of f.keys()) this.users[ref].add(cell);
    this.compute(cell);
    this.propagate(cell);
    return this.val[cell];
  }
}

